const INVOICES = {
  'inv-1': { invoice_id: 'inv-1', amount: 100, currency: 'USD', status: 'paid' }
};

function toolError(code, message) {
  const err = new Error(message);
  err.code = code;
  return err;
}

export async function listTools() {
  return [
    {
      name: 'lookup_invoice',
      description: 'Look up an invoice by its invoice id.',
      inputSchema: {
        type: 'object',
        properties: {
          invoice_id: { type: 'string', description: 'The invoice identifier.' }
        },
        required: ['invoice_id'],
        additionalProperties: false
      }
    }
  ];
