  const invoice = INVOICES[invoice_id];
  if (!invoice) {
    throw toolError('NOT_FOUND', `Invoice not found: ${invoice_id}`);
  }
  return {
    content: [{ type: 'text', text: JSON.stringify(invoice) }]
  };
}
